-- Nouveau mode « carte_en_ligne », canal et référence sur paiements (ALTER au lieu de reconstruction)
ALTER TABLE paiements DROP CONSTRAINT paiements_mode_check;
ALTER TABLE paiements ADD CONSTRAINT paiements_mode_check CHECK(mode IN('especes','virement','mobile_money','carte_en_ligne'));
ALTER TABLE paiements ADD COLUMN canal TEXT NOT NULL DEFAULT 'guichet' CHECK(canal IN('guichet','en_ligne'));
ALTER TABLE paiements ADD COLUMN reference TEXT;
CREATE TABLE paiements_en_ligne(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token TEXT UNIQUE NOT NULL, eleve_id INTEGER NOT NULL REFERENCES eleves(id), parent_id INTEGER NOT NULL REFERENCES users(id),
 montant_millimes INTEGER NOT NULL CHECK(montant_millimes>0), statut TEXT NOT NULL DEFAULT 'en_attente' CHECK(statut IN('en_attente','paye','echoue','annule','expire')),
 fournisseur TEXT NOT NULL DEFAULT 'simulation', paiement_id INTEGER REFERENCES paiements(id), created_at TEXT NOT NULL DEFAULT now_txt());
ALTER TABLE matieres ADD COLUMN couleur TEXT;
ALTER TABLE matieres ADD COLUMN icone TEXT;
CREATE TABLE felicitations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eleve_id INTEGER NOT NULL REFERENCES eleves(id), enseignant_id INTEGER NOT NULL REFERENCES users(id), motif TEXT NOT NULL,
 icone TEXT NOT NULL DEFAULT 'etoile', date TEXT NOT NULL DEFAULT to_char(timezone('utc',now()),'YYYY-MM-DD'), annee_scolaire TEXT NOT NULL);
CREATE INDEX idx_felic_eleve ON felicitations(eleve_id);
